-- SQLite port of the Sakila/Pagila schema (torture test, Part 2).
-- Hand-ported from devrimgunduz/pagila's pagila-schema.sql. Dropped, and
-- documented in docs/torture-test-log.md as known boundaries (not JauntyQ
-- bugs): views, triggers, materialized views, PL/pgSQL functions, the
-- `fulltext` tsvector column on film, and Postgres declarative partitioning
-- on payment (collapsed to one plain table here). `special_features`
-- (Postgres text[]) is stored as a comma-joined TEXT column.
--
-- Data below is a curated, deterministic subset of the real Pagila dataset
-- (not the full ~16k-row rental/payment tables) chosen for parity with
-- schema.postgres.sql in JauntyQ.Sakila.Postgres.Tests: dimension tables
-- (category, language, country, city, actor, film, film_actor,
-- film_category, store, staff) are kept in full; fact tables (address,
-- customer, inventory, rental, payment) are the customer_id % 20 = 1 subset.
-- Both files are generated from the same Postgres source so row-for-row
-- diffing across dialects is meaningful.

PRAGMA foreign_keys = ON;

CREATE TABLE category (
    category_id  INTEGER PRIMARY KEY,
    name         TEXT NOT NULL,
    last_update  TEXT NOT NULL
);

CREATE TABLE language (
    language_id  INTEGER PRIMARY KEY,
    name         TEXT NOT NULL,
    last_update  TEXT NOT NULL
);

CREATE TABLE country (
    country_id   INTEGER PRIMARY KEY,
    country      TEXT NOT NULL,
    last_update  TEXT NOT NULL
);

CREATE TABLE city (
    city_id      INTEGER PRIMARY KEY,
    city         TEXT NOT NULL,
    country_id   INTEGER NOT NULL REFERENCES country(country_id),
    last_update  TEXT NOT NULL
);

CREATE TABLE actor (
    actor_id     INTEGER PRIMARY KEY,
    first_name   TEXT NOT NULL,
    last_name    TEXT NOT NULL,
    last_update  TEXT NOT NULL
);

CREATE TABLE film (
    film_id               INTEGER PRIMARY KEY,
    title                 TEXT NOT NULL,
    description           TEXT,
    release_year          INTEGER,
    language_id           INTEGER NOT NULL REFERENCES language(language_id),
    original_language_id  INTEGER REFERENCES language(language_id),
    rental_duration       INTEGER NOT NULL DEFAULT 3,
    rental_rate           NUMERIC NOT NULL DEFAULT 4.99,
    length                INTEGER,
    replacement_cost      NUMERIC NOT NULL DEFAULT 19.99,
    rating                TEXT DEFAULT 'G',
    last_update           TEXT NOT NULL,
    special_features      TEXT
);

CREATE TABLE film_actor (
    actor_id     INTEGER NOT NULL REFERENCES actor(actor_id),
    film_id      INTEGER NOT NULL REFERENCES film(film_id),
    last_update  TEXT NOT NULL,
    PRIMARY KEY (actor_id, film_id)
);

CREATE TABLE film_category (
    film_id      INTEGER NOT NULL REFERENCES film(film_id),
    category_id  INTEGER NOT NULL REFERENCES category(category_id),
    last_update  TEXT NOT NULL,
    PRIMARY KEY (film_id, category_id)
);

CREATE TABLE address (
    address_id   INTEGER PRIMARY KEY,
    address      TEXT NOT NULL,
    address2     TEXT,
    district     TEXT NOT NULL,
    city_id      INTEGER NOT NULL REFERENCES city(city_id),
    postal_code  TEXT,
    phone        TEXT NOT NULL,
    last_update  TEXT NOT NULL
);

CREATE TABLE store (
    store_id           INTEGER PRIMARY KEY,
    manager_staff_id   INTEGER NOT NULL,
    address_id         INTEGER NOT NULL REFERENCES address(address_id),
    last_update        TEXT NOT NULL
);

CREATE TABLE staff (
    staff_id     INTEGER PRIMARY KEY,
    first_name   TEXT NOT NULL,
    last_name    TEXT NOT NULL,
    address_id   INTEGER NOT NULL REFERENCES address(address_id),
    email        TEXT,
    store_id     INTEGER NOT NULL REFERENCES store(store_id),
    active       INTEGER NOT NULL DEFAULT 1,
    username     TEXT NOT NULL,
    password     TEXT,
    last_update  TEXT NOT NULL
);

CREATE TABLE customer (
    customer_id  INTEGER PRIMARY KEY,
    store_id     INTEGER NOT NULL REFERENCES store(store_id),
    first_name   TEXT NOT NULL,
    last_name    TEXT NOT NULL,
    email        TEXT,
    address_id   INTEGER NOT NULL REFERENCES address(address_id),
    activebool   INTEGER NOT NULL DEFAULT 1,
    create_date  TEXT NOT NULL,
    last_update  TEXT,
    active       INTEGER
);

CREATE TABLE inventory (
    inventory_id  INTEGER PRIMARY KEY,
    film_id       INTEGER NOT NULL REFERENCES film(film_id),
    store_id      INTEGER NOT NULL REFERENCES store(store_id),
    last_update   TEXT NOT NULL
);

CREATE TABLE rental (
    rental_id     INTEGER PRIMARY KEY,
    rental_date   TEXT NOT NULL,
    inventory_id  INTEGER NOT NULL REFERENCES inventory(inventory_id),
    customer_id   INTEGER NOT NULL REFERENCES customer(customer_id),
    return_date   TEXT,
    staff_id      INTEGER NOT NULL REFERENCES staff(staff_id),
    last_update   TEXT NOT NULL
);

CREATE TABLE payment (
    payment_id    INTEGER PRIMARY KEY,
    customer_id   INTEGER NOT NULL REFERENCES customer(customer_id),
    staff_id      INTEGER NOT NULL REFERENCES staff(staff_id),
    rental_id     INTEGER NOT NULL REFERENCES rental(rental_id),
    amount        NUMERIC NOT NULL,
    payment_date  TEXT NOT NULL
);

